Method.Source:
/// <summary>
/// Modified method
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(InventTransferParmReceive, InventTransferParmTable_ReceiveUpdateQty), FormControlEventType::Modified), SuppressBPWarning("@MET:BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void InventTransferParmTable_ReceiveUpdateQty_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun                     element                         = sender.formRun();
    FormDataSource              inventTransferParmTable_DS      = element.dataSource(formDataSourceStr(InventTransferParmReceive, InventTransferParmTable));
    FormDataSource              inventTransferParmLine_DS       = element.dataSource(formDataSourceStr(InventTransferParmReceive, InventTransferParmLine));
    InventTransferParmTable     inventTransferParmTable         = inventTransferParmTable_DS.cursor();
    InventTransferParmLine      inventTransferParmLine          = inventTransferParmLine_DS.cursor();

    if (inventTransferParmTable.ReceiveUpdateQty == InventTransferReceiveUpdateQty::Shipment)
    {
        inventTransferParmLine.METCases         = 0;
        inventTransferParmLine.QtyReceiveNow    = 0;
    }

    ttsbegin;
    while select forupdate inventTransferParmLine
        where inventTransferParmLine.TransferId == inventTransferParmTable.TransferId
            && inventTransferParmLine.ParmId == inventTransferParmTable.ParmId
    {
        inventTransferParmLine.METUOM           = 'EA';
        inventTransferParmLine.METSellUOM       = inventTransferParmLine.itemSellUOM(inventTransferParmLine);
        inventTransferParmLine.METCases         = inventTransferParmLine.itemConvertCases(inventTransferParmLine);
        inventTransferParmLine.METOrigQty       = inventTransferParmLine.QtyReceiveNow;
        inventTransferParmLine.METOrigCases     = inventTransferParmLine.METCases;
        inventTransferParmLine.update();
    }
    ttscommit;
}
